import { useCallback, useEffect, useState } from "react";
import {
  DEFAULT_PLATFORM_MODULES,
  STORAGE_KEY,
  type PlatformModule,
} from "@/config/platform-modules";

function mergeWithDefaults(saved: PlatformModule[]): PlatformModule[] {
  const locked = DEFAULT_PLATFORM_MODULES.find((m) => m.locked);
  const byId = new Map(saved.map((m) => [m.id, m]));

  // AI Security Assessment is admin-only hub card — keep in defaults, filter at render
  if (byId.has("custom-1")) {
    byId.delete("custom-1");
  }

  const merged: PlatformModule[] = [];

  if (locked) {
    merged.push({ ...locked, ...byId.get(locked.id), locked: true, route: locked.route, status: "live" });
    byId.delete(locked.id);
  }

  for (const mod of byId.values()) {
    if (mod.locked) continue;
    if (!merged.some((m) => m.id === mod.id)) {
      const def = DEFAULT_PLATFORM_MODULES.find((d) => d.id === mod.id);
      merged.push(def ? { ...def, title: mod.title, description: mod.description } : mod);
    }
  }

  for (const def of DEFAULT_PLATFORM_MODULES) {
    if (def.locked) continue;
    if (!merged.some((m) => m.id === def.id)) merged.push(def);
  }

  return merged;
}

function loadModules(): PlatformModule[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [...DEFAULT_PLATFORM_MODULES];
    const parsed = JSON.parse(raw) as PlatformModule[];
    if (!Array.isArray(parsed) || parsed.length === 0) return [...DEFAULT_PLATFORM_MODULES];
    return mergeWithDefaults(parsed);
  } catch {
    return [...DEFAULT_PLATFORM_MODULES];
  }
}

export function usePlatformModules() {
  const [modules, setModules] = useState<PlatformModule[]>(loadModules);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(modules));
  }, [modules]);

  const updateModule = useCallback((id: string, patch: Partial<Pick<PlatformModule, "title" | "description">>) => {
    setModules((prev) =>
      prev.map((m) => {
        if (m.id !== id) return m;
        if (m.locked) return { ...m, description: patch.description ?? m.description };
        return { ...m, ...patch };
      }),
    );
  }, []);

  const addModule = useCallback(() => {
    const n = modules.filter((m) => m.id.startsWith("custom-")).length + 1;
    setModules((prev) => [
      ...prev,
      {
        id: `custom-${Date.now()}`,
        title: `Section ${n}`,
        description: "Click edit to rename this block",
        icon: "layers",
        gradient: "from-slate-500 to-slate-700",
        status: "soon" as const,
      },
    ]);
  }, [modules]);

  const removeModule = useCallback((id: string) => {
    setModules((prev) => prev.filter((m) => m.id !== id && !m.locked));
  }, []);

  const resetModules = useCallback(() => {
    setModules([...DEFAULT_PLATFORM_MODULES]);
  }, []);

  return { modules, updateModule, addModule, removeModule, resetModules };
}
